--!strict
-- VFX: turns an entry of VFXLibrary (generated by vfx.py) into a ready ParticleEmitter.
-- 1. Upload the preset's PNG, paste its id into VFXLibrary (AssetId). Put VFX and VFXLibrary side by side.
-- 2. local e = VFX.make("explosion", somePart)       -- Enabled = false
-- 3. e:Emit(1) for one-shots; e.Enabled = true for loops (black-hole).
local Library = require(script.Parent:WaitForChild("VFXLibrary"))

local VFX = {}

local ORIENT = {
	FacingCamera = Enum.ParticleOrientation.FacingCamera,
	VelocityParallel = Enum.ParticleOrientation.VelocityParallel,
	VelocityPerpendicular = Enum.ParticleOrientation.VelocityPerpendicular,
}

function VFX.make(id: string, parent: Instance, studs: number?): ParticleEmitter
	local e = Library[id]
	assert(e, "VFX: unknown effect " .. id)
	assert(e.AssetId ~= 0, "VFX: upload " .. e.file .. " and set its AssetId first")
	local p = Instance.new("ParticleEmitter")
	p.Name = id
	p.Texture = "rbxassetid://" .. tostring(e.AssetId)
	p.FlipbookLayout = Enum.ParticleFlipbookLayout[e.FlipbookLayout]
	local loop = e.FlipbookMode == "Loop"
	p.FlipbookMode = if loop then Enum.ParticleFlipbookMode.Loop else Enum.ParticleFlipbookMode.OneShot
	if e.FlipbookFramerate then
		p.FlipbookFramerate = NumberRange.new(e.FlipbookFramerate)
		p.FlipbookStartRandom = true
	end
	-- loops: each particle lives 4 cycles and fades in/out; two overlap, so the loop never pops
	local life = if loop then e.Lifetime * 4 else e.Lifetime
	p.Lifetime = NumberRange.new(life)
	if loop then
		p.Transparency = NumberSequence.new({
			NumberSequenceKeypoint.new(0, 1), NumberSequenceKeypoint.new(0.2, 0),
			NumberSequenceKeypoint.new(0.8, 0), NumberSequenceKeypoint.new(1, 1),
		})
	end
	p.LightEmission = e.LightEmission
	p.LightInfluence = e.LightInfluence or 0   -- the sheet already carries its own lighting
	p.Size = NumberSequence.new(studs or (e.SizeStuds[1] + e.SizeStuds[2]) / 2)
	p.Orientation = ORIENT[e.Orientation]
	p.Speed = NumberRange.new(0)
	p.Rotation = NumberRange.new(0)
	p.RotSpeed = NumberRange.new(0)
	p.Rate = if loop then 2 / life else 0
	p.LockedToPart = true
	p.Enabled = false
	p.Parent = parent
	return p
end

return VFX
